xql_query:
// ============================================================
// Rule: WIN_Suspicious Sandboxie DLL Load from Non-Standard Path
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Suspicious Sandboxie DLL Load from Non-Standard Path.
// Severity: SEV_030_MEDIUM
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1574.001 - Hijack Execution Flow: DLL Search Order Hijacking

config case_sensitive = false

| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.LOAD_IMAGE

| alter module_path = lowercase(action_module_path)

// DLL específica do comportamento observado
| filter module_path ~= ".*\\\\sbiedll\\.dll$"

// Exclui caminhos legítimos do Sandboxie
| filter module_path !~= "^c:\\\\program files\\\\sandboxie."
| filter module_path !~= "^c:\\\\program files\\\\sandboxie-plus."
| filter module_path !~= "^c:\\\\programdata\\\\sbie\\\\core\\\\.*"

| fields
    _time,
    agent_hostname,
    agent_id,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_module_path,
    action_module_sha256,
    event_type,
    event_sub_type
